static int find(int[] a, int target, int lo, int hi) {
    if (lo > hi) {
        return -1;
    }
    int mid = (lo + hi) / 2;
    if (a[mid] == target) {
        return mid;
    }
    if (a[mid] < target) {
        return find(a, target, mid + 1, hi);
    }
    return find(a, target, lo, mid - 1);
}

