static boolean isPal(String s) {
    if (s.length() <= 1) {
        return true;
    }
    if (!s.substring(0, 1).equals(s.substring(s.length() - 1))) {
        return false;
    }
    return isPal(s.substring(1, s.length() - 1));
}

System.out.println(isPal("racecar") + " " + isPal("ab"));

static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

